/* Static skeletons reflect real image requests, with an explicit failure state. */
(()=>{const seen=new WeakSet();function watch(img){if(seen.has(img)||!img.getAttribute('src'))return;seen.add(img);if(img.complete&&img.naturalWidth)return;const host=img.parentElement;if(!host)return;host.classList.add('rm-image-pending');const state=document.createElement('span');state.className='rm-image-state';state.setAttribute('role','status');state.setAttribute('aria-label','Loading image');state.innerHTML='<i></i><i></i><i></i>';host.append(state);const done=()=>{host.classList.remove('rm-image-pending');state.remove()};const failed=()=>{host.classList.remove('rm-image-pending');host.classList.add('rm-media-error');state.textContent='Preview unavailable. Reload to retry.';state.setAttribute('aria-label',state.textContent)};img.addEventListener('load',done,{once:true});img.addEventListener('error',failed,{once:true});if(img.complete){if(img.naturalWidth)done();else failed()}}function scan(){document.querySelectorAll('img').forEach(watch)}new MutationObserver(scan).observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['src','srcset']});scan()})();
